var countOperations = function(num1, num2) {
    let ans = 0;
    while (num1 > 0 && num2 > 0) {
        if (num1 >= num2) {
            ans += Math.floor(num1 / num2);
            num1 %= num2;
        } else {
            ans += Math.floor(num2 / num1);
            num2 %= num1;
        }
    }
    return ans;
};
